import { type Polygon, centroid, transformPolygon } from '../geom/polygon';
import { type Iso, IDENTITY, compose, reflection, isoKey, isDirect, apply } from '../geom/isometry';
import { dist } from '../geom/vec';

export interface DevelopmentGroup {
  /** orientation-preserving elements (the group G⁺ when the tile is Coxeter) */
  direct: Iso[];
  /** every element found, mirrored ones included */
  all: Iso[];
  truncated: boolean;
}

/**
 * Breadth-first enumeration of the group generated by reflections in the edges
 * of `base`, keeping elements whose image of the centroid lies within `radius`.
 * For a Coxeter polygon this is the development of its pillowcase; for any
 * other polygon the images overlap, which the UI shows deliberately.
 */
export function developmentGroup(base: Polygon, radius: number, maxCount = 2000): DevelopmentGroup {
  const c = centroid(base);
  const refl = base.map((p, i) => reflection(p, base[(i + 1) % base.length]!));
  const seen = new Map<string, Iso>();
  const queue: Iso[] = [IDENTITY];
  seen.set(isoKey(IDENTITY), IDENTITY);
  let truncated = false;
  while (queue.length) {
    const g = queue.shift()!;
    for (const r of refl) {
      const h = compose(g, r);
      if (dist(apply(h, c), c) > radius) continue;
      const k = isoKey(h);
      if (seen.has(k)) continue;
      if (seen.size >= maxCount) {
        truncated = true;
        break;
      }
      seen.set(k, h);
      queue.push(h);
    }
    if (truncated) break;
  }
  const all = [...seen.values()];
  return { direct: all.filter(isDirect), all, truncated };
}

export const placeAll = (isos: Iso[], poly: Polygon): Polygon[] => isos.map((g) => transformPolygon(g, poly));
